// 共 127 份考卷、254 題：{'學測': 18, '學測模考': 72, '指考模考': 14, '總複習卷': 23}
// 欄位：id, type（學測／學測模考／指考模考／總複習卷）, year（學年度，總複習卷為 0）, title,
//       items:[{zh 中文題目, en:[參考譯文…], src:'模考詳解'（取自考卷詳解）|'AI'（原卷未附譯文，AI 參考譯文）}]
const TRANSLATION_SETS = [{"id": "gsat115","type": "學測","year": 115,"title": "115 學測","items": [{"zh": "現在越來越多高中英文老師已經增加在課堂上使用英文的百分比。","en": ["Nowadays, more and more high school English teachers have increased the percentage of English used in class."],"src": "AI"},{"zh": "他們將學生依英語能力分成不同組別，進行多樣的聽、說活動。","en": ["They divide students into different groups according to their English ability and carry out various listening and speaking activities."],"src": "AI"}]},{"id": "gsat114","type": "學測","year": 114,"title": "114 學測","items": [{"zh": "人類的想像和創意是科技進步最大的驅動力。","en": ["Human imagination and creativity are the greatest driving force behind technological progress."],"src": "AI"},{"zh": "過去在科幻電影中出現的神奇物件，現在正逐一成真。","en": ["The amazing objects that appeared in science fiction movies in the past are now coming true one by one."],"src": "AI"}]},{"id": "gsat113","type": "學測","year": 113,"title": "113 學測","items": [{"zh": "每逢選舉季節，總會看到政治人物造訪各地著名廟宇。","en": ["During every election season, we can always see politicians visiting famous temples around the country."],"src": "AI"},{"zh": "除了祈求好的選舉結果，他們也希望展現對在地文化與習俗的尊重。","en": ["Besides praying for good election results, they also hope to show their respect for local culture and customs."],"src": "AI"}]},{"id": "gsat112","type": "學測","year": 112,"title": "112 學測","items": [{"zh": "歷史一再證明，戰爭會造成極為可怕的災難。","en": ["History has proven again and again that war causes extremely terrible disasters."],"src": "AI"},{"zh": "避免衝突、確保世界和平應該是所有人類追求的目標。","en": ["Avoiding conflicts and ensuring world peace should be the goal that all human beings pursue."],"src": "AI"}]},{"id": "gsat111","type": "學測","year": 111,"title": "111 學測","items": [{"zh": "飼養寵物並非一項短暫的人生體驗，而是一個對動物的終生承諾。","en": ["Keeping a pet is not a short-term life experience but a lifelong commitment to the animal."],"src": "AI"},{"zh": "在享受寵物所帶來的歡樂時，我們不該忽略要善盡照顧他們的責任。","en": ["While enjoying the happiness that pets bring us, we should not neglect our responsibility to take good care of them."],"src": "AI"}]},{"id": "gsat110","type": "學測","year": 110,"title": "110 學測","items": [{"zh": "根據新聞報導，每年全球有超過百萬人在道路事故中喪失性命。","en": ["According to news reports, more than a million people around the world lose their lives in road accidents every year."],"src": "AI"},{"zh": "因此，交通法規必須嚴格執行，以確保所有用路人的安全。","en": ["Therefore, traffic laws must be strictly enforced to ensure the safety of all road users."],"src": "AI"}]},{"id": "gsat110t","type": "學測","year": 110,"title": "110 學測試辦考試","items": [{"zh": "很多人害怕公開演講，常在上台之前發抖、覺得頭昏。","en": ["Many people are afraid of speaking in public and often tremble and feel dizzy before going on stage."],"src": "AI"},{"zh": "只要我們對自己有信心，並持續練習，就可以克服怯場的問題。","en": ["As long as we have confidence in ourselves and keep practicing, we can overcome stage fright."],"src": "AI"}]},{"id": "gsat109","type": "學測","year": 109,"title": "109 學測","items": [{"zh": "我們有時會違背自己的意願去做某些事情，就只為了要取悅朋友。","en": ["Sometimes we do things against our will just to please our friends."],"src": "AI"},{"zh": "其實，在面對同儕壓力的時候，我們應該學習堅持自己的原則。","en": ["In fact, when facing peer pressure, we should learn to stick to our own principles."],"src": "AI"}]},{"id": "gsat108","type": "學測","year": 108,"title": "108 學測","items": [{"zh": "自2007年營運以來，高鐵（the High Speed Rail）已成為臺灣最便利、最快速的交通工具之一。","en": ["Since it began operating in 2007, the High Speed Rail has become one of the most convenient and fastest means of transportation in Taiwan."],"src": "AI"},{"zh": "對於強調職場效率的人而言，高鐵當然是商務旅行的首選。","en": ["For those who value efficiency in the workplace, the High Speed Rail is certainly the first choice for business trips."],"src": "AI"}]},{"id": "gsat107","type": "學測","year": 107,"title": "107 學測","items": [{"zh": "近年來，有越來越多超級颱風，通常造成嚴重災害。","en": ["In recent years, there have been more and more super typhoons, which usually cause serious damage."],"src": "AI"},{"zh": "颱風來襲時，我們應準備足夠的食物，並待在室內，若有必要，應迅速移動至安全的地方。","en": ["When a typhoon hits, we should prepare enough food and stay indoors; if necessary, we should move to a safe place quickly."],"src": "AI"}]},{"id": "gsat106","type": "學測","year": 106,"title": "106 學測","items": [{"zh": "玉山(Jade Mountain)在冬天常常覆蓋著厚厚的積雪，使整個山頂閃耀如玉。","en": ["Jade Mountain is often covered with thick snow in winter, which makes the whole summit shine like jade."],"src": "AI"},{"zh": "征服玉山一直是國內外登山者最困難的挑戰之一。","en": ["Conquering Jade Mountain has always been one of the most difficult challenges for climbers at home and abroad."],"src": "AI"}]},{"id": "gsat105","type": "學測","year": 105,"title": "105 學測","items": [{"zh": "相較於他們父母的世代，現今年輕人享受較多的自由和繁榮。","en": ["Compared with their parents' generation, young people today enjoy more freedom and prosperity."],"src": "AI"},{"zh": "但是在這個快速改變的世界中，他們必須學習如何有效地因應新的挑戰。","en": ["However, in this rapidly changing world, they must learn how to deal with new challenges effectively."],"src": "AI"}]},{"id": "gsat104","type": "學測","year": 104,"title": "104 學測","items": [{"zh": "一個成功的企業不應該把獲利當作最主要的目標。","en": ["A successful business should not regard making profits as its main goal."],"src": "AI"},{"zh": "它應該負起社會責任，以增進大眾的福祉。","en": ["It should take on social responsibility to promote the well-being of the public."],"src": "AI"}]},{"id": "gsat103","type": "學測","year": 103,"title": "103 學測","items": [{"zh": "有些年輕人辭掉都市裡的高薪工作，返回家鄉種植有機蔬菜。","en": ["Some young people quit their high-paying jobs in the city and returned to their hometowns to grow organic vegetables."],"src": "AI"},{"zh": "藉由決心與努力，很多人成功了，不但獲利更多，還過著更健康的生活。","en": ["With determination and hard work, many of them have succeeded, not only making more profit but also living a healthier life."],"src": "AI"}]},{"id": "gsat102","type": "學測","year": 102,"title": "102 學測","items": [{"zh": "都會地區的高房價對社會產生了嚴重的影響。","en": ["High housing prices in metropolitan areas have had a serious impact on society."],"src": "AI"},{"zh": "政府正推出新的政策，以滿足人們的住房需求。","en": ["The government is launching new policies to meet people's housing needs."],"src": "AI"}]},{"id": "gsat101","type": "學測","year": 101,"title": "101 學測","items": [{"zh": "近年來，許多臺灣製作的影片已經受到國際的重視。","en": ["In recent years, many films made in Taiwan have received international attention."],"src": "AI"},{"zh": "拍攝這些電影的地點也成為熱門的觀光景點。","en": ["The places where these movies were shot have also become popular tourist attractions."],"src": "AI"}]},{"id": "gsat100","type": "學測","year": 100,"title": "100 學測","items": [{"zh": "臺灣的夜市早已被認為足以代表我們的在地文化。","en": ["Taiwan's night markets have long been regarded as representative of our local culture."],"src": "AI"},{"zh": "每年它們都吸引了成千上萬來自不同國家的觀光客。","en": ["Every year, they attract thousands of tourists from different countries."],"src": "AI"}]},{"id": "gsat99","type": "學測","year": 99,"title": "99 學測","items": [{"zh": "在過去，腳踏車主要是作為一種交通工具。","en": ["In the past, bicycles were mainly used as a means of transportation."],"src": "AI"},{"zh": "然而，騎腳踏車現在已經成為一種熱門的休閒活動。","en": ["However, riding bicycles has now become a popular leisure activity."],"src": "AI"}]},{"id": "id174","type": "學測模考","year": 115,"title": "115 全國學測模擬考（E1）","items": [{"zh": "去海外讀書不僅是為了獲得知識，更是為了培養獨立性。","en": ["Studying abroad is not only for gaining knowledge but also for developing independence."],"src": "模考詳解"},{"zh": "除了探索新環境，學生們也有機會學會如何面對各種艱難的挑戰。","en": ["Besides exploring new environments, students also have the opportunity to learn how to deal with various difficulties."],"src": "模考詳解"}]},{"id": "id181","type": "學測模考","year": 115,"title": "115 全國學測模擬考（E2）","items": [{"zh": "線上學習平台提供了豐富的資源，讓學生可以根據自己的步調學習，而不再受限於地理位置。","en": ["Online learning platforms provide abundant resources, allowing students to learn at their own pace without being restricted by geographical location anymore."],"src": "模考詳解"},{"zh": "除了節省了通勤時間以外，這種學習方式也讓偏遠地區的人們有機會接受高品質的教育。","en": ["In addition to saving commuting time, this approach to learning gives people in remote areas the opportunity to receive high-quality education."],"src": "模考詳解"}]},{"id": "id186","type": "學測模考","year": 115,"title": "115 全國學測模擬考（E3）","items": [{"zh": "曾在外語教學中佔有重要地位的文法，如今已不再受到多數學習者的重視。","en": ["Grammar, which used to play an important role in foreign language teaching, is no longer valued by most learners."],"src": "AI"},{"zh": "事實上，能正確使用文法確實可以幫助我們有效溝通並避免不必要的誤解。","en": ["In fact, being able to use grammar correctly can indeed help us communicate effectively and avoid unnecessary misunderstandings."],"src": "AI"}]},{"id": "id184","type": "學測模考","year": 115,"title": "115 全國學測模擬考（第2次）","items": [{"zh": "近年來，臺灣的旅遊產業因為旅館費用高昂而大幅衰退。","en": ["In recent years, Taiwan's tourism industry has declined significantly due to high hotel costs."],"src": "模考詳解"},{"zh": "為了善用旅遊預算，越來越多人寧可出國旅遊，也不願意安排國內旅行。","en": ["To make better use of their travel budget, more and more people would travel abroad rather than arrange domestic trips."],"src": "模考詳解"}]},{"id": "id160","type": "學測模考","year": 114,"title": "114 全模學測（E2）","items": [{"zh": "在這個藝廊裡有很多塑膠製成的文創商品，其中大部分是由王先生創作的。","en": ["In this gallery, there are many cultural and creative products made of plastic, and most of them are created by Mr. Wang."],"src": "模考詳解"},{"zh": "他之前需要做的就是看見塑膠廢棄物的價值，並將垃圾轉變成藝術。","en": ["All he needed to do before was to see the value of plastic waste and transform garbage into art."],"src": "模考詳解"}]},{"id": "id168","type": "學測模考","year": 114,"title": "114 全模學測（E3）","items": [{"zh": "隨著大眾健康意識的持續提升，街上出現了越來越多的健身中心。","en": ["As public health awareness continues to rise, more and more fitness centers have appeared on the streets."],"src": "AI"},{"zh": "在所有運動形式中，我最喜歡慢跑，因為我唯一需要的就是一雙好的跑步鞋。","en": ["Of all forms of exercise, I like jogging best because the only thing I need is a good pair of running shoes."],"src": "AI"}]},{"id": "id172","type": "學測模考","year": 114,"title": "114 南一學測模擬考（第2次）","items": [{"zh": "詐騙案件的數量持續增加，大多數的受害者為老年人。","en": ["The number of fraud cases keeps increasing, and most of the victims are elderly people."],"src": "AI"},{"zh": "一個保護自己的方法就是避免向陌生人透露個人資訊。","en": ["One way to protect yourself is to avoid revealing personal information to strangers."],"src": "AI"}]},{"id": "id170","type": "學測模考","year": 114,"title": "114 南一學測模擬考（第4次）","items": [{"zh": "許多雇主在面試中問出乎意料的問題，以觀察求職者如何回應。","en": ["Many employers ask unexpected questions during interviews to observe how candidates respond."],"src": "模考詳解"},{"zh": "這些問題沒有標準答案，而是用來評估他們的邏輯思考能力。","en": ["These questions have no standard answers, but they are used to evaluate their logical thinking skills."],"src": "模考詳解"}]},{"id": "id162","type": "學測模考","year": 114,"title": "114 學測模擬考（第1次）","items": [{"zh": "不少城市在推動人行道擴建時，常遇到來自當地居民的反對。","en": ["Many cities often face opposition from local residents when promoting sidewalk expansion."],"src": "模考詳解"},{"zh": "有些商家擔心人行道的擴建會使顧客進出他們的商店變得不方便，進而影響生意。","en": ["Some shop owners worry that sidewalk expansions will make it inconvenient for customers to enter and exit their stores, affecting business."],"src": "模考詳解"}]},{"id": "id171","type": "學測模考","year": 114,"title": "114 學測模擬考（第3次）","items": [{"zh": "隨著人們年齡增長，他們的反應速度和視力通常會下降，這可能會增加駕駛時發生交通意外的風險。","en": ["As people get older, their reaction time and vision usually decline, which may increase the risk of traffic accidents while driving."],"src": "模考詳解"},{"zh": "雖然可能引發爭議，但為了用路者的安全，政府應該要求高齡駕駛定期健康檢查。","en": ["Even though it may cause controversy, the government should require that elderly drivers have regular health checkups for the safety of road users."],"src": "模考詳解"}]},{"id": "id150","type": "學測模考","year": 113,"title": "113 全國學測模擬考（E1）","items": [{"zh": "大部分臺灣高中生期待參加由學校舉辦的畢業旅行。","en": ["Most high school students in Taiwan look forward to going on the graduation trip held by their school."],"src": "AI"},{"zh": "他們可以在不同觀光景點欣賞美景，並拍下難忘的照片。","en": ["They can enjoy the beautiful scenery at different tourist spots and take unforgettable photos."],"src": "AI"}]},{"id": "id157","type": "學測模考","year": 113,"title": "113 全模學測","items": [{"zh": "疫情趨緩之際，全球旅遊需求激增，許多人渴望探索外國景點。","en": ["As the pandemic eases, global travel demand has increased tremendously, with many people eager to explore overseas tourist attractions."],"src": "模考詳解"},{"zh": "當地經濟隨著旅遊業的復甦而受益，創造了大量的就業機會。","en": ["The local economies have benefited from the recovery of the tourism industry, creating a large number of job opportunities."],"src": "模考詳解"}]},{"id": "id163","type": "學測模考","year": 113,"title": "113 全模學測（第4次）","items": [{"zh": "透過團隊合作，我們可以更有效率地達成目標，因為團隊的力量往往比個人的更大。","en": ["Through teamwork, we can achieve our goals more efficiently because the power of a team is often greater than that of an individual."],"src": "AI"},{"zh": "相較於單獨工作，合作讓我們能結合不同的技能和觀點來產生更好的結果。","en": ["Compared with working alone, cooperation allows us to combine different skills and perspectives to produce better results."],"src": "AI"}]},{"id": "id155","type": "學測模考","year": 113,"title": "113 北北基學測模擬考（E2）","items": [{"zh": "因應臺灣人口老化問題，政府已經提供長照服務以減少家庭的負擔。","en": ["In response to Taiwan's aging population, the government has provided long-term care services to reduce the burden on families."],"src": "AI"},{"zh": "當年長者不再能獨立生活時，他們需要各式各樣的服務選項在日常生活中協助他們。","en": ["When the elderly can no longer live independently, they need a wide variety of service options to help them in their daily lives."],"src": "AI"}]},{"id": "id165","type": "學測模考","year": 113,"title": "113 北北基學測模擬考（翰林）","items": [{"zh": "隨著網路幾乎到處都可取得，許多人偏好玩線上遊戲勝於參加戶外活動。","en": ["As the Internet is accessible almost everywhere, many people prefer playing online games to participating in outdoor activities."],"src": "模考詳解"},{"zh": "然而，世界衛生組織（WHO）將線上遊戲上癮視為一種會導致憂鬱症的心理疾病。","en": ["However, WHO regards being addicted to online games as a kind of mental illness which can cause depression."],"src": "模考詳解"}]},{"id": "id156","type": "學測模考","year": 113,"title": "113 北模學測","items": [{"zh": "為了未來的世代，在日常生活中減少塑膠垃圾是一項重要的任務。","en": ["For future generations, reducing plastic waste in our daily life is an important mission."],"src": "模考詳解"},{"zh": "許多餐廳和飲料店會提供折扣或折價券，以鼓勵顧客攜帶自己的容器。","en": ["Many restaurants and drink shops provide discounts or coupons to encourage customers to bring their own containers."],"src": "模考詳解"}]},{"id": "id151","type": "學測模考","year": 113,"title": "113 南一學測模擬考（第1次）","items": [{"zh": "為了節約資源並減少對環境的衝擊，我們應該減少消費和購買永續產品。","en": ["To conserve resources and lessen environmental impact, we should reduce consumption and purchase sustainable products."],"src": "模考詳解"},{"zh": "此外，避免使用一次性塑膠可以減少污染並有益於生態系統。","en": ["Moreover, avoiding single-use plastics decreases pollution and benefits ecosystems."],"src": "模考詳解"}]},{"id": "id144","type": "學測模考","year": 112,"title": "112 中區學測模擬考（第1次）","items": [{"zh": "愈來愈多青少年意識到，在社群網路上的負面訊息已經造成他們嚴重的心理負擔。","en": ["A growing number of teenagers are aware that negative news on social media has become a serious mental burden for them."],"src": "模考詳解"},{"zh": "然而，就算閱讀那些留言會導致憂鬱，他們就是會忍不住看那些傷人的評論。","en": ["However, even if reading those messages leads to depression, they just can't help reading those hurtful comments."],"src": "AI"}]},{"id": "id146","type": "學測模考","year": 112,"title": "112 全國學測模擬考","items": [{"zh": "社交媒體創造了一個表達自我、建立聯繫和獲取資訊的新平臺。","en": ["Social media has created a new platform for self-expression, connecting with others, and obtaining information."],"src": "模考詳解"},{"zh": "通過設定界限和提倡負責任的使用，社交媒體可以成為個人和社會發展的寶貴工具。","en": ["By setting boundaries and promoting responsible use, social media can be a valuable tool for personal and social development."],"src": "模考詳解"}]},{"id": "id135","type": "學測模考","year": 112,"title": "112 全國學測模擬考（E1）","items": [{"zh": "近幾年來，智慧型手機似乎已經成為我們日常生活中必要的通訊工具。","en": ["In recent years, smartphones seem to have become a necessary communication tool in our daily lives."],"src": "AI"},{"zh": "當我們遭遇到嚴重的意外事件時，我們可以立即用手機與我們的家人聯繫。","en": ["When we encounter a serious accident, we can contact our family immediately with our phones."],"src": "AI"}]},{"id": "id142","type": "學測模考","year": 112,"title": "112 全國學測模擬考（新竹 B1-B4）","items": [{"zh": "因應全球暖化和空汙嚴重的議題，近期世界各國都宣布能源節約的目標。","en": ["In response to issues of global warming and serious air pollution, countries worldwide have announced their goals of energy conservation recently."],"src": "模考詳解"},{"zh": "為達到能源節約的要求，各車廠都致力於電動車的發展。","en": ["To meet the demand for energy conservation, all car manufacturers are dedicated to the development of electric vehicles."],"src": "模考詳解"}]},{"id": "id137","type": "學測模考","year": 112,"title": "112 全模學測（文昌第1次）","items": [{"zh": "現在，科學家可以在實驗室裡從活的動物身上提取少量細胞，並將其培養成肉品。","en": ["Nowadays, scientists are able to take few cells from living animals in labs and grow them into meat."],"src": "模考詳解"},{"zh": "實驗室人造肉品不會產生大量的溫室氣體，因此對地球更有益，也對動物更友善。","en": ["Lab-grown meat doesn't produce a lot of greenhouse gases, so it is better for the earth and also more friendly to animals."],"src": "模考詳解"}]},{"id": "id149","type": "學測模考","year": 112,"title": "112 北模學測（12月）","items": [{"zh": "當地居民不被允許靠近那棟有倒塌風險的舊大樓。","en": ["Local residents are not allowed to get close to the old building that is at the risk of collapsing."],"src": "模考詳解"},{"zh": "市長已經宣布直到問題解決之後，這項禁令才會廢除。","en": ["The mayor has announced that the ban will not be lifted until the problem is solved."],"src": "模考詳解"}]},{"id": "id140","type": "學測模考","year": 112,"title": "112 學測模擬考（11202）","items": [{"zh": "我的同事是一位愛冒險的遊客，常常造訪大部分臺灣人不熟的國家。","en": ["My colleague is an adventurous traveler, often visiting countries that are unfamiliar to most Taiwanese people."],"src": "模考詳解"},{"zh": "儘管有潛在的風險，到那些地方旅遊可以滿足他的好奇心，並豐富他的生活。","en": ["Despite potential risks, traveling to those places can satisfy his curiosity and enrich his life."],"src": "模考詳解"}]},{"id": "id147","type": "學測模考","year": 112,"title": "112 學測模擬考（第4次）","items": [{"zh": "購物習慣的改變影響全球消費市場，因此如何善用行銷資源成為成功的關鍵。","en": ["Changes in shopping habits affect the global consumer market; therefore, how to make the most of marketing resources has become the key to success."],"src": "模考詳解"},{"zh": "透過分析銷售數據與創新產品，許多公司已成功地提升產品的商業價值。","en": ["By analyzing sales data and innovating products, many companies have successfully enhanced the commercial value of their products."],"src": "模考詳解"}]},{"id": "id141","type": "學測模考","year": 112,"title": "112 學測聯合模擬考（第2次）","items": [{"zh": "禽流感疫情造成的雞蛋短缺，近幾年內將難以避免。","en": ["The shortage of eggs caused by avian flu is unlikely to be avoided in the coming years."],"src": "模考詳解"},{"zh": "儘管擔心，人們還是應該記得不要一次買太多，因為雞蛋的保鮮期很短。","en": ["Though worried, people should remember not to buy too many eggs at a time because eggs have a very short shelf life."],"src": "模考詳解"}]},{"id": "id113","type": "學測模考","year": 111,"title": "111 中區學測模擬考（第1次）","items": [{"zh": "在新冠肺炎疫情期間，許多公司讓員工在家遠距辦公。","en": ["During the COVID-19 pandemic, many companies let their employees work remotely from their homes."],"src": "模考詳解"},{"zh": "雖然居家辦公承諾給予更多自由，有些員工難以把工作和居家生活分開來。","en": ["Although working from home promises more freedom, some workers have difficulty separating work life from home life."],"src": "模考詳解"}]},{"id": "id122","type": "學測模考","year": 111,"title": "111 全國學測模擬考（E3）","items": [{"zh": "如果你打算存錢，有理財計畫並追蹤所有的花費是很重要的。","en": ["If you want to save money, it is very important to have a financial plan and keep track of all the money you spend."],"src": "模考詳解"},{"zh": "只有當你知道錢被花在哪裡，你才能設定合理的預算並達成目標。","en": ["Only when you know where your money is spent can you set a reasonable budget and achieve the goal."],"src": "模考詳解"}]},{"id": "id116","type": "學測模考","year": 111,"title": "111 全國學測模擬考（E4）","items": [{"zh": "根據這份研究指出，氣候變遷在未來十年中將會對許多地區的農作物造成劇烈的影響。","en": ["According to this research, climate change will have a dramatic influence on crop yields in many areas in the next decade."],"src": "模考詳解"},{"zh": "因此，我們似乎不應再把充分的食物供應視為理所當然的事情。","en": ["Therefore, it seems that we should no longer take sufficient food supply for granted."],"src": "模考詳解"}]},{"id": "id132","type": "學測模考","year": 111,"title": "111 全國學測模擬考（第1次）","items": [{"zh": "對享受自然景色的人來說，騎單車環繞臺灣是人生最重要的里程碑之一。","en": ["For people who enjoy natural scenery, cycling around Taiwan is one of the most important milestones in life."],"src": "模考詳解"},{"zh": "儘管這可能是艱鉅的挑戰，規律的訓練和飲食可以讓人們更容易成功。","en": ["Despite the fact that this might be a tough challenge, regular training and diet can make it easier for people to succeed."],"src": "模考詳解"}]},{"id": "id134","type": "學測模考","year": 111,"title": "111 全模學測","items": [{"zh": "騎單車不僅可以降低污染也能增進人際與家庭關係，它是最健康的運動與生活方式之一。","en": ["Cycling can not only reduce pollution but also improve personal and family relationships; it is one of the healthiest sports and lifestyles."],"src": "AI"},{"zh": "儘管騎單車的趨勢在台灣一直快速成長，但相較於一些歐洲先進國家，仍還有很大的進步空間。","en": ["Although the cycling trend has been growing rapidly in Taiwan, there is still much room for improvement compared with some advanced European countries."],"src": "AI"}]},{"id": "id125","type": "學測模考","year": 111,"title": "111 北區學測模擬考（第1次）","items": [{"zh": "培養有效的讀書習慣是很值得的，因為如此做能幫助增進我們的學習。","en": ["It is worthwhile to cultivate effective study habits because doing so helps enhance our learning."],"src": "模考詳解"},{"zh": "可行的方法包含對我們所學保持興趣，以及除去任何讓我們對課業分心的事物。","en": ["Practical ways include staying interested in what we learn and removing anything that distracts us from our studies."],"src": "模考詳解"}]},{"id": "id118","type": "學測模考","year": 111,"title": "111 北市學測模擬考（B2）","items": [{"zh": "由於其低犯罪率，臺灣已被網路票選為世界上第二最安全的國家。","en": ["Owing to its low crime rate, Taiwan has been voted online as the second safest country in the world."],"src": "模考詳解"},{"zh": "然而，令外國旅客十分氣惱的是，許多臺灣的駕駛人不願禮讓行人。","en": ["However, much to the annoyance of foreign travelers, many Taiwanese drivers are reluctant to yield to pedestrians."],"src": "模考詳解"}]},{"id": "id130","type": "學測模考","year": 111,"title": "111 南一學測模擬考","items": [{"zh": "令我們難過的是，發生在附近一棟老舊大樓的大火造成許多人喪命。","en": ["To our sadness, the huge fire that broke out in an old building nearby killed many people."],"src": "模考詳解"},{"zh": "為了避免類似的意外，政府應該負起責任並調查意外起因。","en": ["To prevent a similar accident, the government should take the responsibility and investigate the cause of the accident."],"src": "模考詳解"}]},{"id": "id120","type": "學測模考","year": 111,"title": "111 南一學測模擬考（第4次）","items": [{"zh": "生而為人，我厭倦我人生中每個階段所伴隨而來的責任。","en": ["As a human being, I am fed up with the duties accompanied by every step of my life."],"src": "模考詳解"},{"zh": "我多希望當一隻寵物，活在一種沒有社會期望與經濟壓力的生活中。","en": ["How I wish I could be a pet, living a life without social expectations and economic burdens."],"src": "模考詳解"}]},{"id": "id128","type": "學測模考","year": 111,"title": "111 學測模擬考（E1）","items": [{"zh": "法國禁止多種水果及蔬菜以塑膠包裝，希望能終結過度包裝的問題。","en": ["France bans plastic wrapping used on many kinds of fruits and vegetables, hoping to put an end to the problem of overpackaging."],"src": "模考詳解"},{"zh": "一項民意調查也指出，將近六成的英國人對於超市無法提供更多可重複使用或無包裝的產品感到失望與沮喪。","en": ["A poll also indicates that nearly 60 percent of the British people are disappointed and frustrated that supermarkets fail to provide more reusable or packaging-free products."],"src": "模考詳解"}]},{"id": "id115","type": "學測模考","year": 111,"title": "111 學測模擬考（第6次）","items": [{"zh": "一見到網路上刊登的高薪海外工作，很多人未確認真實性便應徵。","en": ["Upon reading about the high-paying overseas jobs posted on the Internet, lots of people applied for them without checking the authenticity."],"src": "模考詳解"},{"zh": "直到抵達目的地，護照被扣押，他們才發現自己已經落入工作詐騙的陷阱。","en": ["Not until they got to the destination with their passports taken away did they realize that they had fallen into the trap of job scams."],"src": "模考詳解"}]},{"id": "id126","type": "學測模考","year": 111,"title": "111 文昌學測模擬考","items": [{"zh": "在許多貧窮國家，女性教育通常既不被當地人接受，也不被重視。","en": ["In many poor countries, women's education is often neither accepted by local people nor valued."],"src": "AI"},{"zh": "政府應執行婦女識字方案，幫助她們獲得更多的教育和平等。","en": ["The government should carry out literacy programs for women to help them gain more education and equality."],"src": "AI"}]},{"id": "id105","type": "學測模考","year": 110,"title": "110 中區學測模擬考","items": [{"zh": "現今，愈來愈多的人重視居家布置，而其中最受歡迎的項目就是室內植栽。","en": ["Nowadays, more and more people value interior decorations, and one of the most popular items is indoor plants."],"src": "模考詳解"},{"zh": "有些綠色植物甚至更可以淨化空氣，不知不覺中改善我們的健康。","en": ["Some green plants can even purify the air, improving our health without our knowledge."],"src": "模考詳解"}]},{"id": "id111","type": "學測模考","year": 110,"title": "110 全模學測（E4）","items": [{"zh": "在社群媒體上，常常有廣告推銷各式各樣的商品，從日常必需品到電子產品都有。","en": ["There are often advertisements that promote a variety of products on social media, from daily necessities to electronic products."],"src": "模考詳解"},{"zh": "然而，有很高比例的消費者最後收到仿冒品，或是有瑕疵的產品，且很難要求退款。","en": ["However, a high percentage of consumers end up receiving fakes or defective products, and have a hard time asking for a refund."],"src": "模考詳解"}]},{"id": "id98","type": "學測模考","year": 110,"title": "110 全模學測（南一第1次）","items": [{"zh": "近年來，極端氣候已成為新常態，不意外地，因天氣而引發的災害在未來會愈來愈常見。","en": ["In recent years, extreme climate has become the new normal; it is no surprise that disasters caused by weather will become more and more common in the future."],"src": "模考詳解"},{"zh": "大眾必須了解日常活動如何影響環境，而且政府要制定政策並做好準備，以因應未知的危機。","en": ["The public has to understand how everyday activities affect the environment, and the government should make policies and be well prepared for unexpected crises."],"src": "模考詳解"}]},{"id": "id110","type": "學測模考","year": 110,"title": "110 全模學測（南一第4次）","items": [{"zh": "隨著環保意識的高漲，愈來愈多人覺得該是時候當個理智的消費者，並且停止重複購買不必要的東西。","en": ["With the rise of environmental awareness, more and more people think it is time to be a sensible shopper and stop buying unnecessary things repeatedly."],"src": "模考詳解"},{"zh": "對於實行簡單生活的人而言，他們最在意的是生活的品質而非追隨時尚流行。","en": ["For those who live a simple life, what they care about most is the quality of life rather than following the trend."],"src": "模考詳解"}]},{"id": "id104","type": "學測模考","year": 110,"title": "110 北模學測（B1）","items": [{"zh": "臺灣是座四面環海的島嶼，因此不但擁有美麗的海岸線，還有豐富的海洋資源。","en": ["Taiwan is an island surrounded by the sea, so it has not only beautiful coastlines but also rich marine resources."],"src": "AI"},{"zh": "為了保育珍貴的自然環境，該是教育民眾如何保護海洋的時候了。","en": ["To preserve the precious natural environment, it is time to educate the public on how to protect the ocean."],"src": "AI"}]},{"id": "id108","type": "學測模考","year": 110,"title": "110 北模學測（B2）","items": [{"zh": "近年來，能源短缺已變成全球性的問題，迫使臺灣政府想出替代方案。","en": ["Recently, power shortage has become a global problem, which forces the Taiwanese government to come up with alternative plans."],"src": "模考詳解"},{"zh": "雖然臺灣偶爾發生停電，但是長期下來有些工廠仍遭受到經濟損失。","en": ["Although Taiwan occasionally has electricity blackouts, some factories still suffer economic loss in the long run."],"src": "模考詳解"}]},{"id": "id107","type": "學測模考","year": 110,"title": "110 學測聯合模擬考（第3次）","items": [{"zh": "面對新課綱（curriculum guideline）所帶來的改變，老師與學生們都須努力適應。","en": ["Facing the changes brought about by the new curriculum guideline, both teachers and students have to try hard to adapt to them."],"src": "模考詳解"},{"zh": "儘管覺得挫折或擔憂，我們仍應記得所有的努力都將是值得的。","en": ["Though feeling frustrated or worried, we should remember that all efforts will pay off."],"src": "模考詳解"}]},{"id": "id96","type": "學測模考","year": 110,"title": "110 新北基學測模擬考（第2次）","items": [{"zh": "近年來，間歇性斷食（intermittent fasting）已成為流行的趨勢，因為有愈來愈多人使用它來維持身材。","en": ["In recent years, intermittent fasting has become a popular trend because more and more people have used it to keep their figures."],"src": "模考詳解"},{"zh": "有些人深信間歇性斷食是有效的減重方式而且能幫助預防疾病。","en": ["Some people deeply believe that intermittent fasting is an effective way to lose weight and can help prevent diseases."],"src": "模考詳解"}]},{"id": "id101","type": "學測模考","year": 110,"title": "110 竹區學測模擬考","items": [{"zh": "在現今社會中，多數人堅稱沒有足夠的時間來達成工作與家庭的要求。","en": ["In today's society, most people insist that they do not have enough time to meet the demands of work and family."],"src": "AI"},{"zh": "即使有很多省時的裝置來促進他們的工作效率，很多人仍然過著沒有休閒活動的忙碌生活。","en": ["Even though there are many time-saving devices to improve their work efficiency, many people still live busy lives without leisure activities."],"src": "AI"}]},{"id": "id94","type": "學測模考","year": 109,"title": "109 中區學測模擬考（第1次）","items": [{"zh": "面對頂尖的桌球選手，這位年輕選手從未害怕而是展現出絕佳的天分與抗壓性。","en": ["Facing top table tennis players, this young player never fears but displays great talent and resistance to stress."],"src": "模考詳解"},{"zh": "在訪談中，他謙虛地表示唯有不斷的學習與練習才能擊敗對手。","en": ["In the interview, he said with humility that only through constant learning and practice could he defeat his opponent."],"src": "模考詳解"}]},{"id": "id93","type": "學測模考","year": 109,"title": "109 中區學測模擬考（第3次）","items": [{"zh": "在面對任何的危機時，真正的領導者有信心與勇氣挺身而出並做出困難但正確的決定。","en": ["In the face of any crisis, a true leader has the confidence and courage to stand out and make tough but right decisions."],"src": "模考詳解"},{"zh": "此外，聆聽人們的需求並團結人民與政府一同渡過難關也是必要的。","en": ["Besides, listening to people's needs and uniting people and the government to overcome difficulties are also necessary."],"src": "模考詳解"}]},{"id": "id92","type": "學測模考","year": 109,"title": "109 北區學測模擬考（第2次）","items": [{"zh": "隨著智慧手機的普及，愈來愈多的年輕人受到社群媒體影響。","en": ["With the popularity of smart phones, more and more young people are affected by social media."],"src": "模考詳解"},{"zh": "根據一項美國的調查，超過七成的青少年希望未來成為網紅。","en": ["According to an American survey, more than seventy percent of teenagers hope to become Internet celebrities in the future."],"src": "模考詳解"}]},{"id": "id95","type": "學測模考","year": 109,"title": "109 學測模擬考（第2次）","items": [{"zh": "由於社群媒體的便利性，各式各樣的訊息，未經證實就在人與人之間廣為流傳。","en": ["Due to the convenience of social media, all kinds of information is spreading widely among people without being confirmed."],"src": "模考詳解"},{"zh": "因此，除非我們確定訊息正確，否則不應轉傳，以免造成不必要的麻煩。","en": ["Therefore, unless we are sure the information is accurate, we should not pass it on in order not to cause unnecessary trouble."],"src": "模考詳解"}]},{"id": "id90","type": "學測模考","year": 109,"title": "109 翰林全國學測模擬考（E1）","items": [{"zh": "幾個月前有一個住在臺灣的外國 YouTuber 上傳一則影片，其中他以母語列舉出五項臺灣最棒的事物。","en": ["A couple of months ago, a foreign YouTuber living in Taiwan posted a video in which he listed the top five things about Taiwan in his mother tongue."],"src": "模考詳解"},{"zh": "他認為臺灣是一個值得認識的地方，所以決定介紹臺灣給家鄉的人們。","en": ["He thought Taiwan is a place worth knowing, so he decided to introduce it to the people back home."],"src": "模考詳解"}]},{"id": "id91","type": "學測模考","year": 109,"title": "109 翰林全國學測模擬考（E2）","items": [{"zh": "群眾募資平臺（Crowdfunding platforms）使得有創意的人可以向網友募資，用以贊助範圍從商業產品到競選活動的方案。","en": ["Crowdfunding platforms have enabled creative people to raise money from netizens to fund projects ranging from commercial products to election campaigns."],"src": "模考詳解"},{"zh": "藉由捐款給相關機構，我們不僅可以協助這些人們實現夢想，還可以把愛傳下去。","en": ["By donating money to related organizations, we can not only help people fulfill their dreams but also pay it forward."],"src": "模考詳解"}]},{"id": "id86","type": "學測模考","year": 108,"title": "108 北模學測（第1次）","items": [{"zh": "最近，臺灣許多關於食品安全的新聞讓大家都很害怕吃外食。","en": ["Recently, a lot of news about food safety in Taiwan has made people afraid to eat out."],"src": "模考詳解"},{"zh": "瓶裝水很方便，但丟棄的空瓶子會對環境有負面影響。","en": ["Bottled water is convenient, but the discarded bottles can have negative effects on the environment."],"src": "模考詳解"}]},{"id": "id84","type": "學測模考","year": 108,"title": "108 北模學測（第2次）","items": [{"zh": "透過網際網路，你不僅可以和任何人做朋友，且不出門也可以享受網路購物的樂趣。","en": ["Through the Internet, you can not only make friends with anyone but also enjoy online shopping without leaving home."],"src": "AI"},{"zh": "另外，網路可以幫你省下很多的時間及精力，大大地增進你的效率。","en": ["Besides, the Internet can save you a lot of time and energy, greatly improving your efficiency."],"src": "AI"}]},{"id": "id74","type": "學測模考","year": 107,"title": "107 北模學測（第1次）","items": [{"zh": "當名人採取行動時，他們很容易就能提升公眾意識，而成為改變的力量。","en": ["When celebrities take action, they can easily raise public awareness, becoming a force for change."],"src": "模考詳解"},{"zh": "例如，看到明星說 \"Me too\"，更多人也會有勇氣挺身而出。","en": ["For example, seeing stars saying \"Me too,\" more people will stand out with courage."],"src": "模考詳解"}]},{"id": "id76","type": "學測模考","year": 107,"title": "107 北模學測（第2次）","items": [{"zh": "由於逐漸惡化的汙染問題，政府一直在強調節約能源的重要性。","en": ["Because of the worsening problem of pollution, the government has been putting stress on the importance of energy saving."],"src": "模考詳解"},{"zh": "為了解決電力不足的問題，發展再生能源也是刻不容緩的。","en": ["To solve the problem of insufficient power, it is urgent to develop sustainable energy."],"src": "模考詳解"}]},{"id": "id88","type": "學測模考","year": 106,"title": "106 中模學測（第1次）","items": [{"zh": "或許香港(Hong Kong)的沒落將會是逐漸的，伴隨著證監會(the SFC)及法庭衰敗。","en": ["Perhaps Hong Kong's decline will be gradual, with the SFC and courts decaying."],"src": "模考詳解"},{"zh": "話雖如此，香港最大的問題之一是它自身的缺乏信心。","en": ["Still, one of Hong Kong's biggest problems is its own lack of confidence."],"src": "模考詳解"}]},{"id": "id78","type": "學測模考","year": 106,"title": "106 中模學測（第2次）","items": [{"zh": "隨著人工智慧的快速發展，機器人已經被廣泛使用在各種領域。","en": ["With the rapid development of artificial intelligence, robots have been widely used in all kinds of fields."],"src": "模考詳解"},{"zh": "機器人不僅可從事危險的工作也可以滿足老人的需求。","en": ["Robots can not only do dangerous jobs but also meet the needs of the elderly."],"src": "模考詳解"}]},{"id": "id64","type": "學測模考","year": 106,"title": "106 北模學測（第1次）","items": [{"zh": "隨著社會變化快速，大人和青少年間的代溝問題已經變得愈來愈嚴重。","en": ["As the society changes so fast, the problem of generation gap between adults and teenagers has become more and more serious."],"src": "模考詳解"},{"zh": "專家建議青少年應該更加注意溝通，而不是只在乎他們自己的自由意志。","en": ["Experts suggest that teenagers should pay more attention to communication instead of just caring about their own free will."],"src": "模考詳解"}]},{"id": "id69","type": "學測模考","year": 106,"title": "106 學測模擬考（第1次）","items": [{"zh": "我們即將來到一個時代，是機器幾乎在所有任務上都能超越人類的時代。","en": ["We are about to enter an era in which machines can outperform humans at almost every task."],"src": "AI"},{"zh": "根據估計，在 30 年內機器人將明顯地取代大約 500 萬的工作。","en": ["It is estimated that within 30 years, robots will obviously replace about five million jobs."],"src": "AI"}]},{"id": "id67","type": "學測模考","year": 106,"title": "106 學測模擬考（第2次）","items": [{"zh": "在忙碌的一天後，許多年輕人喜歡去 KTV 唱歌以抒發工作或課業壓力。","en": ["After a busy day, many young people like to sing at KTV to relieve the pressure from work or schoolwork."],"src": "AI"},{"zh": "但同時 KTV 也是個經常發生衝突的場所，所以也不宜在那裡逗留太晚。","en": ["At the same time, KTV is also a place where conflicts often occur, so it is not a good idea to stay there too late."],"src": "AI"}]},{"id": "xm105-1-4","type": "學測模考","year": 105,"title": "105 全國學測模擬考（第4次）","items": [{"zh": "新生兒的到來總能給一個家庭帶來極大的喜悅。","en": ["The arrival of a newborn always brings great joy to a family."],"src": "模考詳解"},{"zh": "同時，許多首度為人父母者發現照料嬰兒很有挑戰性。","en": ["Meanwhile, many first-time parents find it quite challenging to take care of the baby."],"src": "模考詳解"}]},{"id": "id82","type": "學測模考","year": 105,"title": "105 全模學測（第2次）","items": [{"zh": "很多學生有熬夜的習慣，而且他們很難去掉這項壞習慣。","en": ["Many students are in the habit of staying up, and it is hard for them to get rid of this bad habit."],"src": "模考詳解"},{"zh": "因為缺乏睡眠，他們無法專心，這使得他們考試考不好。","en": ["For lack of sleep, they are unable to focus, which makes them perform badly on exams."],"src": "模考詳解"}]},{"id": "id80","type": "學測模考","year": 105,"title": "105 全模學測（第3次）","items": [{"zh": "許多人玩寶可夢(Pokemon Go)玩得很開心，它鼓勵人們出去外面探索周遭環境。","en": ["Lots of people are having fun playing Pokemon Go, which encourages people to go out and explore the surroundings."],"src": "模考詳解"},{"zh": "人們一發現哪裡可以抓稀罕的怪物，就很快地衝到那裡，而該處的交通就會癱瘓。","en": ["As soon as people know where to catch rare creatures, they rush there in no time, and the traffic there will be jam-packed."],"src": "模考詳解"}]},{"id": "id71","type": "學測模考","year": 105,"title": "105 北模學測（第1次）","items": [{"zh": "近年來有愈來愈多的臺灣年輕人選擇到國外工作。","en": ["In recent years, more and more Taiwanese young people have chosen to work overseas."],"src": "模考詳解"},{"zh": "他們所追求的不僅是高薪，還有更好的生活品質。","en": ["What they pursue is not only a high salary but also a better quality of life."],"src": "模考詳解"}]},{"id": "id66","type": "學測模考","year": 104,"title": "104 北模學測（第1次）","items": [{"zh": "據說吃愈少餐的人，愈容易變瘦。","en": ["It is said that the fewer meals people eat, the easier it is for them to get thin."],"src": "模考詳解"},{"zh": "但是我認為保持身材最好的方法是多運動而不是節食。","en": ["But in my opinion, the best way to keep in shape is to exercise more rather than to go on a diet."],"src": "模考詳解"}]},{"id": "id56","type": "學測模考","year": 102,"title": "102 全國學測模擬考（第3次）","items": [{"zh": "現在手機無所不在，有些人一發現手機不在身邊就開始恐慌。","en": ["These days cellphones are everywhere and some people start to panic as soon as they find their cellphones are not nearby."],"src": "模考詳解"},{"zh": "其實，即使你每天關掉手機數小時，你很少錯過什麼重要的事。","en": ["In fact, you seldom miss anything important even if you turn your cellphone off for several hours each day."],"src": "模考詳解"}]},{"id": "id60","type": "學測模考","year": 102,"title": "102 全國學測模擬考（第4次）","items": [{"zh": "近來好幾件年輕人佔用博愛座的新聞引起大家的關注。","en": ["Recently, several pieces of news that young people took the priority seats have aroused everyone's attention."],"src": "模考詳解"},{"zh": "有時我們也該考量坐在位子上的人是否有不讓座的原因。","en": ["Sometimes we should also consider whether those in the seats have some reasons for not giving up their seats."],"src": "模考詳解"}]},{"id": "id59","type": "學測模考","year": 102,"title": "102 台中學測模擬考（第1次）","items": [{"zh": "在都市工作的人一定都經歷過找不到停車位的困擾。","en": ["People who work in cities must have encountered difficulty finding parking spaces."],"src": "模考詳解"},{"zh": "這也就是為什麼我寧願坐公車，而不願開車上班的原因。","en": ["That is why I would rather take the bus than drive to work."],"src": "AI"}]},{"id": "id58","type": "學測模考","year": 102,"title": "102 臺北區學測模擬考（第2次）","items": [{"zh": "智慧型手機越來越流行，已經成為很多人生活中不可或缺的一部分。","en": ["Smartphones have become more and more popular, and they have become an indispensable part in many people's lives."],"src": "模考詳解"},{"zh": "雖然智慧型手機可以帶來許多便利，但太常使用對健康會有不良的影響。","en": ["Although smartphones can bring lots of convenience, using them too much can have a bad effect on health."],"src": "模考詳解"}]},{"id": "id57","type": "學測模考","year": 102,"title": "102 臺北區學測模擬考（第3次）","items": [{"zh": "這位獲獎的作家鼓勵年輕人要對生命有熱誠，並且要努力追求夢想。","en": ["The prize-awarded writer inspires young people to be enthusiastic about life and make efforts to pursue their dreams."],"src": "模考詳解"},{"zh": "他堅信只要你有恆心和毅力，人生沒有無法克服的障礙。","en": ["He firmly believes that no obstacles cannot be overcome in life as long as you have determination and perseverance."],"src": "模考詳解"}]},{"id": "zk109-2-01","type": "指考模考","year": 109,"title": "109 北模指考（第1次）","items": [{"zh": "由於人類活動，世界各地許多冰河自二十世紀初起快速融化。","en": ["Due to human activities, many glaciers around the world have been melting rapidly since the early 20th century."],"src": "模考詳解"},{"zh": "隨著冰河縮退，許多野生動物像是海豹正失去牠們的棲息地，北極熊也瀕臨滅絕。","en": ["With the shrinking of glaciers, many wild animals, like seals, are losing their habitats, and polar bears are endangered, too."],"src": "模考詳解"}]},{"id": "zk109-2-02","type": "指考模考","year": 109,"title": "109 北模指考（第2次）","items": [{"zh": "近年來愈來愈受歡迎的正向心理學（Positive Psychology），強調的是個人的福祉而非心理疾病的治療。","en": ["Positive Psychology, which has become increasingly popular in recent years, emphasizes individual well-being rather than the treatment of mental illness."],"src": "模考詳解"},{"zh": "研究顯示透過冥想和親密關係，人們能增加快樂感並延長壽命。","en": ["Research suggests that through intimate relationships and meditation, people can increase happiness and prolong their lives."],"src": "模考詳解"}]},{"id": "zk-55","type": "指考模考","year": 109,"title": "109 台中指考模擬考","items": [{"zh": "在這個科技發展快速的時代，許多年輕人偏好使用交友軟體（dating apps）來交朋友。","en": ["In this era when technology develops rapidly, many young people prefer using dating apps to make friends."],"src": "模考詳解"},{"zh": "然而，有些人卻提供假的個人資料，因而導致了許多嚴重的問題。","en": ["However, some people provide fake personal information, leading to many serious problems."],"src": "模考詳解"}]},{"id": "zk1092","type": "指考模考","year": 109,"title": "109 指考模擬考（下學期）","items": [{"zh": "到目前為止，共有三位充滿抱負的學生參選學生會長。","en": ["So far, there have been three ambitious students in total running for president of the student association."],"src": "模考詳解"},{"zh": "為了贏得支持，他們提出五花八門的提案，包括：廢除制服、延後上課時間等。","en": ["To win support, they have put forward various proposals, including abolishing uniforms, postponing school hours and so on."],"src": "模考詳解"}]},{"id": "zk109-e8","type": "指考模考","year": 109,"title": "109 翰林指考模擬考（E8）","items": [{"zh": "除了戶外的空氣汙染，愈來愈多人意識到室內空氣品質的重要性。","en": ["Besides outdoor air pollution, more and more people have realized the importance of indoor air quality."],"src": "AI"},{"zh": "因此，可以移除灰塵、細菌、病毒的空氣清淨機變成生活必需品。","en": ["Therefore, air purifiers that can remove dust, bacteria, and viruses have become a necessity of life."],"src": "AI"}]},{"id": "zk-49","type": "指考模考","year": 109,"title": "指考模擬考 A","items": [{"zh": "一直到畫作被偷竊的新聞被廣泛報導後，The Mona Lisa 才開始備受關注。","en": ["The Mona Lisa did not start to receive attention until the news of its theft had been widely reported."],"src": "模考詳解"},{"zh": "很多人不禁想知道是畫作本身吸引人，還是新聞造就它的名氣。","en": ["Many people can't help but wonder whether it is the painting itself that attracts people or the news that results in its fame."],"src": "模考詳解"}]},{"id": "zk-52","type": "指考模考","year": 109,"title": "指考模擬考 B","items": [{"zh": "在避免疾病散播的許多方法中，洗手與戴口罩是其中最有效的兩種。","en": ["Of the many ways to prevent the spread of diseases, washing hands and wearing face masks are two of the most effective ones."],"src": "模考詳解"},{"zh": "另外，也應該注意群聚感染。畢竟，面對疫情時，我們再怎麼小心也不為過。","en": ["In addition, cluster infection calls for attention, too. After all, we can never be too careful when faced with the pandemic."],"src": "模考詳解"}]},{"id": "zk-54","type": "指考模考","year": 109,"title": "指考模擬考 C","items": [{"zh": "台灣一直以來因美味食物而聞名，吸引許多外國遊客享用街頭食物與典型的台灣料理。","en": ["Taiwan has been famous for delicious food, which attracts many foreign tourists to enjoy street food and classic Taiwanese cuisine."],"src": "模考詳解"},{"zh": "許多遊客因為各式各樣的設施定居在台灣，例如便利商店，他們可深夜在那裡與朋友聚會。","en": ["Many tourists settle in Taiwan because of various facilities, such as convenience stores, where they can gather with friends during midnight."],"src": "模考詳解"}]},{"id": "zk108-2-1","type": "指考模考","year": 108,"title": "108 北模指考（第1次）","items": [{"zh": "為了跟人工智慧（Artificial Intelligence）競爭，學生應該培養多元能力，包括創意及團隊合作等。","en": ["To compete with Artificial Intelligence (AI), students should cultivate multiple abilities, including creativity and teamwork."],"src": "模考詳解"},{"zh": "許多專家建議，廣泛閱讀是有效的方法之一。另外，自主學習也很重要。","en": ["Many experts suggest that extensive reading is one of the effective ways. Besides, autonomous learning is also very important."],"src": "模考詳解"}]},{"id": "zk108-2-2","type": "指考模考","year": 108,"title": "108 北模指考（第2次）","items": [{"zh": "雖然每年流感爆發並奪走許多人命，醫學專家不斷地提醒民眾不要過度恐慌。","en": ["Although the flu breaks out and takes many lives every year, medical experts constantly remind the public not to panic too much."],"src": "模考詳解"},{"zh": "只要我們注重個人衛生，勤洗手和避免去人多擁擠的地方，就比較不可能被感染。","en": ["As long as we pay attention to personal hygiene, wash hands frequently, and avoid going to crowded places, we are less likely to be infected."],"src": "模考詳解"}]},{"id": "zk107-2-3","type": "指考模考","year": 107,"title": "107 北模指考（第3次）","items": [{"zh": "在餐廳用餐時，人們常常太專注在手機上，以致於忽略同桌的家人或朋友。","en": ["When dining in a restaurant, people often focus so much on their smartphones that they ignore their family or friends at the same table."],"src": "模考詳解"},{"zh": "為了有更好的用餐經驗，我們應該避免使用手機，享受主廚準備的食物，並和我們的同伴好好交談。","en": ["To have a better dining experience, we should avoid using our smartphones, enjoy the food prepared by the chef, and have a good conversation with our companions."],"src": "模考詳解"}]},{"id": "zk105-2-6","type": "指考模考","year": 105,"title": "105 全模指考（第6次）","items": [{"zh": "為了尋求鄰近國家的協助，數以百萬計的難民逃離飽受戰火的地區。","en": ["In order to seek help from neighboring countries, millions of refugees fled from war-torn regions.","Millions of refugees escaped from war-torn regions in search of assistance from neighboring nations."],"src": "模考詳解"},{"zh": "然而，因為安全上的威脅，有些國家拒絕接受難民。","en": ["However, some countries refused to take refugees because of a threat to safety."],"src": "模考詳解"}]},{"id": "zk105-2-7","type": "指考模考","year": 105,"title": "105 全模指考（第7次）","items": [{"zh": "國內汽機車數量持續成長，造成交通擁擠及社會資源的浪費。","en": ["The number of cars and motorcycles in our nation continues to grow, which has caused traffic jams and the waste of social resources."],"src": "模考詳解"},{"zh": "此外，這也對空氣品質及民眾健康產生嚴重影響，阻礙環境的永續發展。","en": ["In addition, this has also had serious effects on air quality and people's health, preventing the environment from developing sustainably."],"src": "模考詳解"}]},{"id": "zk105-2-4","type": "指考模考","year": 105,"title": "105 北模指考（第4次）","items": [{"zh": "高中生與同學互動時，有時候可能會覺得受到孤立或缺乏自信。","en": ["When high school students interact with their classmates, sometimes they may feel isolated or lack confidence."],"src": "模考詳解"},{"zh": "即使無法得到同儕的支持，他們仍應該設法保持正向、樂觀。","en": ["Even if they are unable to get any support from their peers, they should try to stay positive and optimistic."],"src": "模考詳解"}]},{"id": "mm01","type": "總複習卷","year": 0,"title": "總複習卷 第一回","items": [{"zh": "養成新的習慣很困難，因為需要改變你現有的生活方式及持續付出努力。","en": ["It is difficult to develop a new habit because it requires changing your current lifestyle and making continuous efforts."],"src": "AI"},{"zh": "從小步驟開始是很重要的，因為這樣你可以逐漸使想要的行為成為日常生活的一部分。","en": ["It is important to start with small steps because this way you can gradually make the desired behavior part of your daily life."],"src": "AI"}]},{"id": "mm02","type": "總複習卷","year": 0,"title": "總複習卷 第二回","items": [{"zh": "大多市面上販售的蔬果外表含有農藥殘留（pesticide residue），一般建議食用前要徹底清洗。","en": ["Most fruits and vegetables sold on the market have pesticide residue on their surface, so it is generally suggested that they be washed thoroughly before eating."],"src": "AI"},{"zh": "去除農藥殘留的最佳方式之一是使用流動的水清洗蔬果至少 30 秒。","en": ["One of the best ways to remove pesticide residue is to wash fruits and vegetables under running water for at least 30 seconds."],"src": "AI"}]},{"id": "mm03","type": "總複習卷","year": 0,"title": "總複習卷 第三回","items": [{"zh": "許多人寧願出國也不願在臺灣旅遊，其中一個主要原因是昂貴的旅館房價。","en": ["Many people would rather travel abroad than travel in Taiwan, and one of the main reasons is the expensive hotel rates."],"src": "AI"},{"zh": "臺灣週末與假日期間的旅館房價明顯要比平日高上許多，這招致了許多批評。","en": ["Hotel rates in Taiwan on weekends and holidays are much higher than on weekdays, which has drawn a lot of criticism."],"src": "AI"}]},{"id": "mm04","type": "總複習卷","year": 0,"title": "總複習卷 第四回","items": [{"zh": "自由就像我們吸入的空氣，對我們來說如此自然，以致於常常被視為理所當然。","en": ["Freedom is like the air we breathe; it is so natural to us that it is often taken for granted."],"src": "AI"},{"zh": "多虧有自由，我們得以做自己並依照自己的信念生活而不用害怕受到迫害（persecute / persecution）。","en": ["Thanks to freedom, we can be ourselves and live according to our own beliefs without fear of being persecuted."],"src": "AI"}]},{"id": "mm05","type": "總複習卷","year": 0,"title": "總複習卷 第五回","items": [{"zh": "隨著環保意識興起，很多人改開電動車，相信電動車對環境的傷害較小。","en": ["With the rise of environmental awareness, many people have switched to electric cars, believing that they do less harm to the environment."],"src": "AI"},{"zh": "然而，電動車還是有一些缺點，如昂貴的電池更換費用和在寒冷天氣表現不佳。","en": ["However, electric cars still have some drawbacks, such as the high cost of battery replacement and poor performance in cold weather."],"src": "AI"}]},{"id": "mm06","type": "總複習卷","year": 0,"title": "總複習卷 第六回","items": [{"zh": "被日本人視為聖山的富士山（Mount Fuji）不僅是日本最高峰也是熱門的旅遊景點。","en": ["Regarded as a sacred mountain by the Japanese, Mount Fuji is not only the highest peak in Japan but also a popular tourist attraction."],"src": "AI"},{"zh": "令人憂慮的是，富士山是一座休眠了 300 多年的活火山，隨時都可能再度噴發（erupt）。","en": ["What is worrying is that Mount Fuji is an active volcano that has been dormant for more than 300 years and may erupt again at any time."],"src": "AI"}]},{"id": "mm07","type": "總複習卷","year": 0,"title": "總複習卷 第七回","items": [{"zh": "最近，兩名臺灣 YouTuber 因為假裝遭到綁架而被柬埔寨（Cambodian）政府判處兩年徒刑。","en": ["Recently, two Taiwanese YouTubers were sentenced to two years in prison by the Cambodian government for faking their own kidnapping."],"src": "AI"},{"zh": "為了吸引追隨者，越來越多網紅製作假影片甚至採取極端行動，這個趨勢令人憂心。","en": ["It is worrying that more and more influencers make fake videos or even take extreme actions to attract followers."],"src": "AI"}]},{"id": "mm08","type": "總複習卷","year": 0,"title": "總複習卷 第八回","items": [{"zh": "你可能曾經注意到一個有趣的現象：越無知的人越有自信。","en": ["You may have noticed an interesting phenomenon: the more ignorant people are, the more confident they are."],"src": "AI"},{"zh": "一個知識有限的人往往會高估自己，並會對非充分了解的事物草率下判斷。","en": ["A person with limited knowledge tends to overestimate himself and make hasty judgments about things he does not fully understand."],"src": "AI"}]},{"id": "mm09","type": "總複習卷","year": 0,"title": "總複習卷 第九回","items": [{"zh": "許多國家在發展過程中以經濟成長為優先，不顧環境的犧牲。","en": ["In the process of development, many countries put economic growth first at the expense of the environment."],"src": "AI"},{"zh": "這些國家直到環境被破壞之後才意識到環境保護的重要性。","en": ["These countries did not realize the importance of environmental protection until the environment had been destroyed."],"src": "AI"}]},{"id": "mm10","type": "總複習卷","year": 0,"title": "總複習卷 第十回","items": [{"zh": "2024 年 4 月 3 日，臺灣東部外海發生大地震，造成超過十人喪生和多人受傷。","en": ["On April 3, 2024, a major earthquake struck off the east coast of Taiwan, killing more than ten people and injuring many others."],"src": "AI"},{"zh": "許多人相信假使震央（epicenter）更靠近臺灣，生命和財產的損失將會嚴重許多。","en": ["Many people believe that if the epicenter had been closer to Taiwan, the loss of lives and property would have been much more serious."],"src": "AI"}]},{"id": "mm11","type": "總複習卷","year": 0,"title": "總複習卷 第十一回","items": [{"zh": "眾所皆知，抽菸對健康有害，而且與肺癌、心臟病這樣的疾病密切相關。","en": ["It is well known that smoking is harmful to health and is closely related to diseases such as lung cancer and heart disease."],"src": "AI"},{"zh": "除了抽菸之外，長期接觸二手煙也可能造成健康風險。","en": ["Besides smoking, long-term exposure to secondhand smoke may also pose health risks."],"src": "AI"}]},{"id": "mm12","type": "總複習卷","year": 0,"title": "總複習卷 第十二回","items": [{"zh": "快時尚（fast fashion）讓人得以用低廉的價格買到新潮服飾，因而在年輕人之間特別受歡迎。","en": ["Fast fashion allows people to buy trendy clothes at low prices, so it is especially popular among young people."],"src": "AI"},{"zh": "然而，該產業也因剝削（exploit / exploitation）勞工與僱用童工而飽受批評。","en": ["However, the industry has also been heavily criticized for exploiting workers and employing child labor."],"src": "AI"}]},{"id": "mm13","type": "總複習卷","year": 0,"title": "總複習卷 第十三回","items": [{"zh": "作為政府風力開發計畫的一部分，臺灣西部沿岸架設了許多風力發電機（wind turbine）。","en": ["As part of the government's wind power development plan, many wind turbines have been set up along the west coast of Taiwan."],"src": "AI"},{"zh": "然而，住在附近的居民抱怨旋轉的扇葉（blade）所產生的噪音和陰影，他們說這些會引發頭痛和睡眠問題。","en": ["However, residents living nearby complain about the noise and shadows caused by the rotating blades, saying that they cause headaches and sleep problems."],"src": "AI"}]},{"id": "mm14","type": "總複習卷","year": 0,"title": "總複習卷 第十四回","items": [{"zh": "許多人將快樂與物質財富聯想在一起，但其實未必越有錢越快樂。","en": ["Many people associate happiness with material wealth, but in fact, being richer does not necessarily make you happier."],"src": "AI"},{"zh": "要得到快樂，你所需要做的是停止與他人作比較並滿足於自己所擁有的一切。","en": ["To be happy, what you need to do is stop comparing yourself with others and be content with everything you have."],"src": "AI"}]},{"id": "mm15","type": "總複習卷","year": 0,"title": "總複習卷 第十五回","items": [{"zh": "2023 年，美國遊民（homeless people）的人數暴增了 70,000 人，是歷年增幅的四倍以上。","en": ["In 2023, the number of homeless people in the United States increased sharply by 70,000, more than four times the annual increase in previous years."],"src": "AI"},{"zh": "為了解決日益嚴重的無家可歸（homelessness）問題，一些城市將貨櫃改成住家以提供遊民一個臨時庇護所。","en": ["To solve the worsening problem of homelessness, some cities have turned shipping containers into homes to provide homeless people with temporary shelters."],"src": "AI"}]},{"id": "mm16","type": "總複習卷","year": 0,"title": "總複習卷 第十六回","items": [{"zh": "今年六月，臺灣蛋價創下近三年來的新低，但多數民眾卻沒有明顯感覺到蛋價下跌。","en": ["This June, egg prices in Taiwan hit their lowest level in nearly three years, but most people did not clearly feel the drop."],"src": "AI"},{"zh": "多數消費者認為餐廳蛋料理的售價有必要隨著蛋價調整。","en": ["Most consumers think that the prices of egg dishes in restaurants should be adjusted along with egg prices."],"src": "AI"}]},{"id": "mm17","type": "總複習卷","year": 0,"title": "總複習卷 第十七回","items": [{"zh": "在許多國家，年輕人夢想成為醫生，主要是因為醫生享有高收入和崇高社會地位。","en": ["In many countries, young people dream of becoming doctors, mainly because doctors enjoy high incomes and high social status."],"src": "AI"},{"zh": "然而，上醫學院很花錢，許多醫學院的畢業生債台高築，可能要花許多年才能還清債務。","en": ["However, medical school is very expensive, and many medical graduates are deep in debt and may take many years to pay it off."],"src": "AI"}]},{"id": "mm18","type": "總複習卷","year": 0,"title": "總複習卷 第十八回","items": [{"zh": "因為地理位置，臺灣易受颱風侵襲，每年平均有三到四個颱風襲擊本島。","en": ["Because of its geographical location, Taiwan is vulnerable to typhoons, with an average of three to four typhoons hitting the island every year."],"src": "AI"},{"zh": "雖然颱風可能造成重大破壞，卻也帶來豪雨，而臺灣仰賴這些降雨取得用水。","en": ["Although typhoons may cause serious damage, they also bring heavy rain, which Taiwan relies on for its water supply."],"src": "AI"}]},{"id": "mm19","type": "總複習卷","year": 0,"title": "總複習卷 第十九回","items": [{"zh": "乘車時，無論你坐在哪裡，在車子啟動前務必要繫上安全帶，因為這能保護你免於在意外中受傷。","en": ["When you are in a car, no matter where you sit, you must fasten your seat belt before the car starts, because it can protect you from being injured in an accident."],"src": "AI"},{"zh": "研究顯示有繫安全帶的人在車禍中死亡的風險比沒有繫安全帶的人低了 50%。","en": ["Studies show that the risk of death in car accidents for people wearing seat belts is 50% lower than for those who do not."],"src": "AI"}]},{"id": "mm20","type": "總複習卷","year": 0,"title": "總複習卷 第二十回","items": [{"zh": "儘管提倡性別平等已多年，許多人對男女外貌依然抱持傳統的性別刻板印象。","en": ["Although gender equality has been promoted for many years, many people still hold traditional gender stereotypes about the appearance of men and women."],"src": "AI"},{"zh": "一個近期的例子是奧運（Olympic）金牌得主林郁婷（Lin Yu-ting），她的性別身份受到許多人質疑，只因為她的外表看起來不像個女人。","en": ["A recent example is Olympic gold medalist Lin Yu-ting, whose gender identity was questioned by many people simply because she did not look like a woman to them."],"src": "AI"}]},{"id": "mm21","type": "總複習卷","year": 0,"title": "總複習卷 第二十一回","items": [{"zh": "臺灣於 1995 年推出全民健康保險計畫（National Health Insurance Program），是少數幾個全體國民享有醫療照護的國家。","en": ["Taiwan launched its National Health Insurance Program in 1995, making it one of the few countries where all citizens enjoy medical care."],"src": "AI"},{"zh": "然而，隨著需要更多醫療照護的老年人口增加以及許多人濫用醫療資源，此制度現今面臨財務危機。","en": ["However, with the growing elderly population needing more medical care and many people abusing medical resources, the system is now facing a financial crisis."],"src": "AI"}]},{"id": "mm22","type": "總複習卷","year": 0,"title": "總複習卷 第二十二回","items": [{"zh": "Hello Kitty 這個日本卡通人物風靡全球 50 年且深受大小朋友所喜愛。","en": ["Hello Kitty, the Japanese cartoon character, has been popular around the world for 50 years and is loved by both children and adults."],"src": "AI"},{"zh": "令很多人驚訝的是，Hello Kitty 並非一隻貓，而是一個在倫敦（London）郊區出生長大的人類女孩。","en": ["To many people's surprise, Hello Kitty is not a cat but a human girl who was born and raised in the suburbs of London."],"src": "AI"}]},{"id": "mm23","type": "總複習卷","year": 0,"title": "總複習卷 第二十三回","items": [{"zh": "多虧了科技的進步，太空旅遊已成為現實，而非僅存在於科幻小說中。","en": ["Thanks to advances in technology, space travel has become a reality instead of existing only in science fiction."],"src": "AI"},{"zh": "為了一睹地球的全貌，許多富豪願意支付天價，展開一場太空探索之旅。","en": ["To see the whole view of the earth, many wealthy people are willing to pay a huge price for a space exploration trip."],"src": "AI"}]}];
